def arrayNesting(A):
    visited = [False] * len(A)
    max_length = 0

    for i in range(len(A)):
        if not visited[i]:
            current_length = 0
            index = i

            while not visited[index]:
                visited[index] = True
                index = A[index]
                current_length += 1

            if current_length > max_length:
                max_length = current_length

    return max_length
